function key(){return 'study:'+child+':'+APP+':v'+V;}
function fresh(){return {schema:V,app:APP,child,session:crypto.randomUUID?.()||String(Date.now())+Math.random().toString(36).slice(2),createdAt:new Date().toISOString(),startedAt:0,finishedAt:0,phase:'home',lesson:0,index:0,attempts:[],reflections:[],drafts:{},marked:{},eliminated:{},exposed:{},syncQueued:false,completed:false,repairQueue:[],repairAt:0,reviewRun:0,previous:[]};}
function save(){try{localStorage.setItem(key(),JSON.stringify(state));unsaved=false;}catch(e){unsaved=true;$('storageNotice').hidden=false;$('storageNotice').textContent='这台设备暂时不能保存。做完请在家长页导出记录。';}}
function loadState(){try{const x=JSON.parse(localStorage.getItem(key()));return valid(x)?x:fresh();}catch{return fresh();}}
function valid(x){return x&&x.schema===V&&x.app===APP&&x.child===child&&Array.isArray(x.attempts)&&Array.isArray(x.reflections)&&typeof x.session==='string'&&Array.isArray(x.previous)&&x.attempts.length<=2000&&Number.isFinite(x.startedAt)&&Number.isFinite(x.finishedAt)&&Number.isInteger(x.lesson)&&x.lesson>=0&&x.lesson<6&&Number.isInteger(x.index)&&x.index>=0&&x.index<=24&&['home','lesson','quiz','review','report'].includes(x.phase)&&['drafts','marked','eliminated','exposed'].every(k=>x[k]&&typeof x[k]==='object'&&!Array.isArray(x[k]));}
function start(){if(state.completed){state.phase='report';render();return;}if(!state.startedAt)state.startedAt=Date.now();state.phase=state.resumePhase||'lesson';save();render();}
function setIdentity(c){if(!['kenton','eddey'].includes(c))return;child=c;params.set('who',c);history.replaceState(null,'',location.pathname+'?'+params);document.body.dataset.child=c;$('who').textContent=c==='kenton'?'Kenton · 哥哥':'Eddey · 弟弟';$('back').href='../subject.html?subject=coding&who='+c;window.DDLearningSync?.setChild(c);state=loadState();questions=makeQuestions();render();clearInterval(timer);timer=setInterval(tick,1000);}
function makeQuestions(){const personal=D.per[child];return [...D.common.filter(q=>!q.code),...personal.filter(q=>!q.code),...D.common.filter(q=>q.code),...personal.filter(q=>q.code)];}
function stopAudio(){if(currentAudio){currentAudio.pause();currentAudio.currentTime=0;}document.querySelectorAll('[data-audio]').forEach(b=>{b.setAttribute('aria-pressed','false');});lastAudio='';if($('soundStatus'))$('soundStatus').textContent='';}
function play(id){const line=D.audio.find(x=>x.id===id);if(!line)return;return; // 旧音色暂停使用
if(lastAudio===id&&currentAudio&&!currentAudio.paused){stopAudio();return;}stopAudio();currentAudio=new Audio(AUDIO_DIR+'/'+id+'.mp3');lastAudio=id;currentAudio.playbackRate=audioRate;currentAudio.preservesPitch=true;currentAudio.onended=()=>{$('soundStatus').textContent='已听完，可以动手试一试。';lastAudio='';document.querySelectorAll('[data-audio]').forEach(b=>b.setAttribute('aria-pressed','false'));};currentAudio.onerror=()=>{stopAudio();$('soundStatus').textContent='这段声音暂时没打开，文字可以照常看。';};currentAudio.play().then(()=>{document.querySelectorAll('[data-audio="'+id+'"]').forEach(b=>b.setAttribute('aria-pressed','true'));$('soundStatus').textContent='正在播放，可再点一次暂停。';}).catch(()=>{$('soundStatus').textContent='请再点一次播放；也可以先看文字。';});}
