function switchView(id){view=id;stopAudio();document.querySelectorAll('[data-view]').forEach(x=>x.hidden=x.dataset.view!==id);window.scrollTo({top:0,behavior:'instant'});}
function tick(){if(!state)return;const remain=state.startedAt?Math.max(0,28*60-Math.floor(((state.finishedAt||Date.now())-state.startedAt)/1000)):28*60;$('clock').textContent=Math.floor(remain/60)+':'+String(remain%60).padStart(2,'0');if(state.startedAt&&!state.finishedAt&&remain===0){state.finishedAt=Date.now();state.completed=true;state.phase='report';state.stopReason='time_limit';save();render();}}
function render(){if(!child){switchView('choose');return;}tick();if(state.phase==='lesson'){renderLesson();}else if(state.phase==='quiz'||state.phase==='review'){renderQuestion();}else if(state.phase==='report'){renderReport();}else{renderHome();}save();}
function renderHome(){switchView('home');drawRouting();$('homeText').textContent='看懂问法，排除错项，把会做的分拿住。';$('homeAudio').innerHTML='';$('start').textContent=state.startedAt&&!state.completed?'继续这次练习':'开始今晚复习';$('daily').textContent=DAILY_SURPRISES[dailyIndex()];$('resumeInfo').textContent=state.startedAt?'本次进度已留在这台设备。':'先看短方法，再做24道四选一；约20—25分钟，可随时收尾。';$('morningHome').hidden=!state.attempts.length;}
function dailyIndex(){const day=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const dailySurpriseKey=APP+'|'+child+'|'+day;return [...dailySurpriseKey].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,0)%DAILY_SURPRISES.length;}
