if(id==='loops'){const doMode=model.mode==='do';const states=doMode?[['从x=5开始',5,0],['先执行 x++',6,0],['检查6<3：假，停止',6,0],['输出x',6,0]]:[['初始值',1,0],['1<4：真，加1，再更新i',2,1],['2<4：真，加2，再更新i',3,3],['3<4：真，加3，再更新i',4,6],['4<4：假，退出循环',4,6],['执行最后的cout',4,6]];const r=states[Math.min(model.step,states.length-1)];const phase=doMode?[1,1,0,3][Math.min(model.step,3)]:[0,2,2,2,0,3][Math.min(model.step,5)];html='<div class="loop-journey">'+['判断','执行','更新','输出'].map((t,i)=>'<span class="'+(i===phase?'current':'')+'">'+t+'</span>').join('')+'</div>'+'<div class="controls compact"><button data-loop="while" aria-pressed="'+!doMode+'">while</button><button data-loop="do" aria-pressed="'+doMode+'">do-while</button></div>'+code(doMode?'int x=5;\ndo { x++; } while(x<3);\ncout << x;':'int i=1,sum=0;\nwhile(i<4){sum+=i; i++;}\ncout << sum << \' \' << i;')+boxes(doMode?[['x · 当前值',r[1]]]:[['i · 当前值',r[1]],['sum · 总和',r[2]]])+'<p class="pointer">'+esc(r[0])+'</p><div class="controls"><button data-action="model-step" '+(model.step>=states.length-1?'disabled':'')+'>执行下一步</button><button data-action="model-reset">从头走</button></div>'; }
